using System;using System.IO;using System.Collections;using System.Collections.Generic;using UnityEngine;using Exoduser.UnityPort.Core;
namespace Exoduser.UnityPort.Tools {internal sealed class ScreenTransitionCheck:MonoBehaviour {
[Serializable]class Check{public string name,detail;public bool passed;}[Serializable]class Sample{public float time,opacity,gain;public bool sigil,label,blocked;public int frame;public string phase;}[Serializable]class Receipt{public string scope="실제 Player 전환 호스트·실제 로비 영상 준비. 테스트 요청은 준비 대기 계약과 구분",runtimeSha,coreSha;public bool passed;public int width,height;public List<Check> checks=new List<Check>();public List<Sample> samples=new List<Sample>();public List<NativeScreenTransition.TransitionRecord> history=new List<NativeScreenTransition.TransitionRecord>();}
static string Arg(string key){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,key);return i>=0&&i+1<a.Length?a[i+1]:null;}[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Boot(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"--unity-transition-check")>=0)new GameObject("Screen transition isolated check").AddComponent<ScreenTransitionCheck>();}
Receipt receipt=new Receipt();string output,phase="prepare";bool recording;float captureAt;NativeLobby lobby;NativeGame game;void C(bool ok,string n,string d=""){receipt.checks.Add(new Check{name=n,passed=ok,detail=d});Debug.Log("TRANSITION_CHECK "+(ok?"PASS ":"FAIL ")+n+" "+d);}
IEnumerator Start(){output=Arg("-output");if(!NativeQaSandbox.Active||string.IsNullOrEmpty(output)||!Path.IsPathRooted(output)){Application.Quit(3);yield break;}Directory.CreateDirectory(output);yield return Guard(Run());}
IEnumerator Guard(IEnumerator run){while(true){bool more=false;object next=null;Exception error=null;try{more=run.MoveNext();if(more)next=run.Current;}catch(Exception e){error=e;}if(error!=null){C(false,"검수 예외",error.ToString());Finish();yield break;}if(!more)yield break;if(next is IEnumerator inner)yield return Guard(inner);else yield return next;}}
IEnumerator Run(){yield return null;game=NativeGame.Instance;lobby=game.GetComponent<NativeLobby>();AudioListener.volume=0;AudioListener.pause=true;lobby.AutomatedInput=false;lobby.SetPlaybackFocus(true);receipt.runtimeSha=Hash(NativeQaAssembly.FilePath(typeof(NativeGame).Assembly));receipt.coreSha=Hash(NativeQaAssembly.FilePath(typeof(Simulation).Assembly));receipt.width=Screen.width;receipt.height=Screen.height;recording=true;StartCoroutine(Frames());
foreach(bool reduced in new[]{false,true}){phase=reduced?"reduced-prepare":"normal-prepare";NativeScreenTransition.ReduceMotion=()=>reduced;int swaps=0,tick=game.Simulation.TickCount;float started=Time.realtimeSinceStartup;int id=NativeScreenTransition.Request(phase,()=>{swaps++;C(NativeScreenTransition.State.Opacity==1,"완전 검정에서만 교체");},()=>Time.realtimeSinceStartup-started>2.1f);C(id>0,"전환 요청 수락");C(NativeScreenTransition.Request("duplicate",()=>swaps++)==0,"중복 요청 거부");yield return Idle();var h=NativeScreenTransition.History[NativeScreenTransition.History.Count-1];C(swaps==1,"교체 한 번");C(h.blackPaintedFrame>0&&h.swappedFrame>h.blackPaintedFrame,"검정 Repaint 다음 프레임 교체",h.blackPaintedFrame+" -> "+h.swappedFrame);C(!h.failed,"실제 준비 완료 뒤 reveal");C(h.swapped-h.started>=(reduced?.075f:.49f),"fade-out 최소 시간",(h.swapped-h.started).ToString("F3"));C(h.finished-h.started>=2.1f+(reduced?.075f:.59f),"준비 대기와 fade-in",(h.finished-h.started).ToString("F3"));C(game.Simulation.TickCount==tick,"전환 중 전투 틱 정지");}
NativeScreenTransition.ReduceMotion=null;phase="real-lobby";lobby.ShowLobby();yield return Idle();phase="real-gate";lobby.ReplayIntro();yield return Idle();phase="real-world";lobby.StartGate();float limit=Time.realtimeSinceStartup+20;while((lobby.CinematicEntryPending||NativeScreenTransition.Busy)&&Time.realtimeSinceStartup<limit)yield return null;C(!lobby.CinematicEntryPending&&!NativeScreenTransition.Busy,"ENTER 1100ms와 영상 전환 종료");C(lobby.CurrentVideo.Prepared&&lobby.CurrentVideo.Frame>=0,"실제 decoder 첫 프레임 준비");C(lobby.Flow.Page==LobbyPage.WorldIntro,"실제 world 페이지");yield return new WaitForSecondsRealtime(.5f);phase="real-return";lobby.ShowLobby();yield return Idle();C(lobby.Flow.Page==LobbyPage.Lobby,"영상에서 로비 복귀");foreach(var h in NativeScreenTransition.History)C(!h.failed&&!h.cancelled,"경계 준비 성공 "+h.boundary,h.error??"");Finish();}
IEnumerator Idle(){float limit=Time.realtimeSinceStartup+18;while(NativeScreenTransition.Busy&&Time.realtimeSinceStartup<limit)yield return null;C(!NativeScreenTransition.Busy,"경계 유한 종료",phase);yield return null;}
IEnumerator Frames(){while(recording){yield return new WaitForEndOfFrame();var f=NativeScreenTransition.State;if(f!=null)receipt.samples.Add(new Sample{time=Time.realtimeSinceStartup,frame=Time.frameCount,phase=phase,opacity=(float)f.Opacity,gain=NativeScreenTransition.Gain,sigil=f.ShowSigil,label=f.ShowLabel,blocked=NativeScreenTransition.InputBlocked});if(Time.realtimeSinceStartup<captureAt)continue;captureAt=Time.realtimeSinceStartup+.25f;var t=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(Path.Combine(output,"frame-"+Time.frameCount+"-"+phase+".png"),t.EncodeToPNG());Destroy(t);}}
static string Hash(string p){using(var s=System.Security.Cryptography.SHA256.Create())using(var f=File.OpenRead(p))return BitConverter.ToString(s.ComputeHash(f)).Replace("-","").ToLowerInvariant();}void Finish(){recording=false;NativeScreenTransition.ReduceMotion=null;receipt.passed=receipt.checks.Count>0&&receipt.checks.TrueForAll(x=>x.passed);if(NativeScreenTransition.History!=null)receipt.history.AddRange(NativeScreenTransition.History);File.WriteAllText(Path.Combine(output,"transition-check.json"),JsonUtility.ToJson(receipt,true));lobby?.CloseStartupCaptureMedia();Application.Quit(receipt.passed?0:2);}
}}
